\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/profiloLorenzo.jpg}}]{Lorenzo Sciacca}{\space}(Graduate Student Member, IEEE) received his M.Sc. in Communications and Computer Network Engineering from Politecnico di Torino, Italy, in 2024. He is currently pursuing a Ph.D. at the Department of Electronics and Telecommunications, Politecnico di Torino, as part of the Navigation Signal Analysis and Simulation (NavSAS) group. His research focuses on developing high-sensitivity, environment-aware GNSS receivers to improve navigation in challenging conditions, including lunar and cis-lunar environments. He has been involved in the Lunar
GNSS Receiver Experiment (LuGRE) since 2025.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/minetto.jpg}}]{Alex Minetto}{\space} (Member, IEEE) received the B.Sc. (2013), M.Sc. (2015), and Ph.D. with honors (2020) in telecommunications and electrical engineering from Politecnico di Torino, where he is now Assistant Professor in the Department of Electronics and Telecommunications and a member of the NavSAS research group. His work focuses on advanced GNSS signal analysis, receiver design, and Bayesian state estimation. He has contributed to ESA and EUSPA projects and since 2021 has been involved in the Lunar GNSS Receiver Experiment (LuGRE) as a mission's Science Team member.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/andrea.jpg}}]{Andrea Nardin} (Member, IEEE) received the M.Sc. (2018) and Ph.D. with honors (2023) in telecommunications and electrical engineering from Politecnico di Torino, where he is now Assistant Professor in the Department of Electronics and Telecommunications and a member of the NavSAS research group. In 2021, he was a Visiting Doctoral Researcher at Northeastern University, Boston. His research interests include signal processing architectures and signal design for GNSS and next-generation PNT systems.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/dovis.jpg}}]{Fabio Dovis} (Member, IEEE) received the M.Sc. (1996) and Ph.D. (2000) from Politecnico di Torino, where he is now Full Professor in the Department of Electronics and Telecommunications and coordinator of the NavSAS Research Group. His research focuses on GNSS receiver design, advanced signal processing for interference and multipath mitigation, and ionospheric monitoring. He has extensive experience in international projects, collaborations with industry and research institutions, and serves on the IEEE AESS Navigation Systems Panel.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/canzian.jpg}}]{Luca Canzian} joined Qascom in 2015 and he is currently leading the R\&D domain area. He has worked in several projects with ESA, ASI, NASA, the European Commission and Industry. His main expertise involves ground-based and space-based location systems, detection and location of interference signals, navigation using signals of opportunity, lunar navigation, inertial navigation systems, orbit determination techniques, GNSS authentication and anti-spoofing techniques. He holds a MSc degree and a PhD in Electrical Engineering from University of Padova (Italy).
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/mario.jpg}}]{Mario Musmeci} received a degree in physics from the University of Rome “La Sapienza.” He has worked with major Italian space companies, ESA, and the European Commission on the Galileo program, and co-founded a start-up exploiting a patent based on Galileo signals for reliable traceability of “Made in Italy” products. Since 2016, he has been with ASI’s Programs Directorate, serving as technical manager for LuGRE on NASA’s Firefly Blue Ghost mission, demonstrating GNSS reception on the lunar surface.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/facchinetti.jpg}}]{Claudia Facchinetti} is a researcher and technologist at the Italian Space Agency (ASI), specializing in Earth observation and space navigation technologies. She holds a Ph.D. in Space Science and Technology and has contributed to numerous scientific projects and space missions, including studies on SAR radar and hyperspectral sensors. She is a key member of the LuGRE (Lunar GNSS Receiver Experiment) team, a joint NASA-ASI initiative that successfully demonstrated GNSS-based navigation on the Moon during the Firefly Blue Ghost Mission 1 in 2025. Additionally, she is responsible for developing Earth observation missions at ASI.
\end{IEEEbiography}

\begin{IEEEbiography}[{\includegraphics[width=1in,height=1.25in,clip,keepaspectratio]{Figures/AuthorPics/varacalli.jpg}}]{Giancarlo Varacalli} received the degree in Electronic Engineering and holds a Master’s degree in Space Systems Engineering from Delft University of Technology. He is currently Head of the Telecommunications and Navigation Department at the Italian Space Agency (ASI). He has held several technical and managerial positions within ASI and serves as Italy’s delegate to ESA programme boards in satellite communications and navigation. His professional interests include satellite telecommunications, navigation systems, and space system engineering.
\end{IEEEbiography}



